import React, { useState, useEffect } from 'react';
import { UserProfile } from '../types';
import { db } from '../services/database';
import { PremiumReservedBankLogo, SpinnerIcon, LockClosedIcon, EyeIcon, EyeSlashIcon, DevicePhoneMobileIcon, ArrowRightIcon, ExclamationCircleIcon, FaceIdIcon, FingerprintIcon, ShieldCheckIcon, CheckCircleIcon } from './Icons';
import { sendOtpSmsViaTextFlow } from '../utils/notificationService';
import { USER_PROFILE } from './constants';
import { triggerHaptic } from '../utils/haptics';

interface WelcomeProps {
    onLogin: (profile: UserProfile) => void;
    onStartCreateAccount: () => void;
    onVerificationRequired: (email: string) => void;
}

const BACKGROUND_IMAGES = [
    "https://lh3.googleusercontent.com/p/AF1QipOt9-a-WR_Fur_p5csZkQerDEWMRkN2VN6Us2xS=s1600", 
    "https://www.eternitylaw.com/wp-content/uploads/2023/07/quebec-city.jpg", 
    "https://wise.com/imaginary-v2/98070557aeeaabfd3fe0aef4b985f6d2.jpg?width=1200", 
    "https://images.unsplash.com/photo-1533929736458-ca588d08c8be?q=80&w=1920&auto=format&fit=crop&ixlib=rb-4.0.3", 
    "https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?q=80&w=1920&auto=format&fit=crop&ixlib=rb-4.0.3", 
    "https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=1920&auto=format&fit=crop&ixlib=rb-4.0.3", 
    "https://images.unsplash.com/photo-1556761175-5973dc0f32e7?q=80&w=1920&auto=format&fit=crop&ixlib=rb-4.0.3"  
];

const DEMO_PHONE_ENDING = "0854";

const BiometricLoginScanner: React.FC<{ onComplete: () => void, onClose: () => void }> = ({ onComplete, onClose }) => {
    const [scanState, setScanState] = useState<'init' | 'scanning' | 'verifying' | 'success'>('init');

    useEffect(() => {
        let timer1: any, timer2: any, timer3: any;

        timer1 = setTimeout(() => {
            setScanState('scanning');
            triggerHaptic([5, 50, 5]);
        }, 800);

        timer2 = setTimeout(() => {
            setScanState('verifying');
            triggerHaptic([10, 10]);
        }, 2500);

        timer3 = setTimeout(() => {
            setScanState('success');
            triggerHaptic([50, 50, 50]);
            setTimeout(onComplete, 1000);
        }, 3800);

        return () => {
            clearTimeout(timer1);
            clearTimeout(timer2);
            clearTimeout(timer3);
        };
    }, [onComplete]);

    return (
        <div className="fixed inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center p-4">
             <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(14,197,242,0.1),transparent_70%)]"></div>
             <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-20 mix-blend-overlay"></div>

             <div className="relative z-10 flex flex-col items-center">
                 <div className="relative w-64 h-64 mb-12">
                     <div className={`absolute inset-0 border border-slate-800 rounded-full transition-all duration-1000 ${scanState === 'scanning' ? 'scale-110 opacity-50 border-primary/30' : 'scale-100'}`}></div>
                     <div className={`absolute inset-4 border border-slate-800 rounded-full transition-all duration-1000 delay-100 ${scanState === 'scanning' ? 'scale-105 opacity-60 border-primary/50' : 'scale-100'}`}></div>

                     <div className={`absolute inset-0 rounded-full overflow-hidden ${scanState === 'scanning' ? 'opacity-100' : 'opacity-0'} transition-opacity duration-500`}>
                        <div className="absolute top-0 left-0 w-full h-2 bg-primary/50 shadow-[0_0_20px_rgba(14,197,242,0.8)] animate-scan-vertical"></div>
                     </div>

                     <div className="absolute inset-0 flex items-center justify-center">
                        <div className={`w-32 h-32 rounded-[2.5rem] bg-slate-900 border border-white/10 flex items-center justify-center shadow-2xl relative overflow-hidden transition-all duration-500 ${scanState === 'success' ? 'border-emerald-500' : 'border-white/10'}`}>
                            {scanState === 'success' ? (
                                <CheckCircleIcon className="w-16 h-16 text-emerald-500 animate-pop-in" />
                            ) : (
                                <FaceIdIcon className={`w-16 h-16 text-white transition-opacity duration-300 ${scanState === 'scanning' ? 'opacity-100' : 'opacity-50'}`} />
                            )}
                        </div>
                     </div>

                     {scanState === 'success' && (
                        <div className="absolute inset-0 border-4 border-emerald-500 rounded-full animate-ping"></div>
                     )}
                 </div>

                 <div className="text-center space-y-2 h-20">
                     <h3 className="text-2xl font-black text-white uppercase tracking-tight animate-fade-in">
                        {scanState === 'init' && "Initializing Enclave..."}
                        {scanState === 'scanning' && "Scanning Biometrics..."}
                        {scanState === 'verifying' && "Verifying Credentials..."}
                        {scanState === 'success' && "Identity Confirmed"}
                     </h3>
                     <p className="text-xs font-bold text-primary uppercase tracking-[0.3em] animate-pulse">
                        {scanState === 'init' && "Establishing Secure Link"}
                        {scanState === 'scanning' && "Processing Face Geometry"}
                        {scanState === 'verifying' && "Matching Hash: 0x8F...2A"}
                        {scanState === 'success' && `Welcome, ${USER_PROFILE.name}`}
                     </p>
                 </div>

                 <button onClick={onClose} className="mt-12 text-slate-500 text-xs font-bold uppercase tracking-widest hover:text-white transition-colors">
                     Cancel Authentication
                 </button>
             </div>

             <style>{`
                @keyframes scan-vertical {
                    0%, 100% { top: 0%; opacity: 0; }
                    10% { opacity: 1; }
                    90% { opacity: 1; }
                    100% { top: 100%; opacity: 0; }
                }
                .animate-scan-vertical {
                    animation: scan-vertical 1.5s cubic-bezier(0.4, 0, 0.2, 1) infinite;
                }
             `}</style>
        </div>
    );
};


export const Welcome: React.FC<WelcomeProps> = ({ onLogin, onStartCreateAccount, onVerificationRequired }) => {
    const [step, setStep] = useState<'credentials' | 'mfa'>('credentials');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [isProcessing, setIsProcessing] = useState(false);
    const [showBiometricScanner, setShowBiometricScanner] = useState(false);
    const [error, setError] = useState('');
    const [authenticatedUser, setAuthenticatedUser] = useState<{ profile: UserProfile; email: string } | null>(null);
    const [mfaCode, setMfaCode] = useState('');
    const [bgIndex, setBgIndex] = useState(0);
    const [isHardwareSupported, setIsHardwareSupported] = useState(false);
    const [generatedOtp, setGeneratedOtp] = useState<string | null>(null);
    const [isResending, setIsResending] = useState(false);

    useEffect(() => {
        const interval = setInterval(() => {
            setBgIndex((prev) => (prev + 1) % BACKGROUND_IMAGES.length);
        }, 8000); 

        if (window.PublicKeyCredential) {
            PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable()
                .then(available => {
                    setIsHardwareSupported(available);
                })
                .catch(err => {
                    console.error("Biometric capability check failed", err);
                    setIsHardwareSupported(false);
                });
        }

        return () => clearInterval(interval);
    }, []);

    const handleLoginSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsProcessing(true);

        try {
            await new Promise(resolve => setTimeout(resolve, 800));
            const result = await db.authenticate(email, password);

            if (result === 'VERIFICATION_REQUIRED') {
                onVerificationRequired(email);
                setIsProcessing(false);
                return;
            }

            if (result && result !== 'VERIFICATION_REQUIRED') {
                setAuthenticatedUser(result);
                // Trigger real/simulated SMS immediately upon credential success
                if (result.profile.phone) {
                    const smsResult = await sendOtpSmsViaTextFlow(result.profile.phone, result.email, result.profile.name);
                    // Store the randomly generated code for validation
                    if (smsResult.code) {
                        setGeneratedOtp(smsResult.code);
                    }
                }
                setStep('mfa');
            } else {
                setError('Invalid user ID or password. Please verify your credentials.');
            }
        } catch (err) {
            console.error("Login failed:", err);
            setError('System error. Please try again or contact support.');
        } finally {
            setIsProcessing(false);
        }
    };

    const handleResendMfa = async () => {
        if (!authenticatedUser?.profile?.phone) return;
        setIsResending(true);
        const smsResult = await sendOtpSmsViaTextFlow(authenticatedUser.profile.phone, authenticatedUser.email, authenticatedUser.profile.name);
        if (smsResult.code) {
            setGeneratedOtp(smsResult.code);
            setError(''); // Clear error if retrying
        }
        setTimeout(() => setIsResending(false), 2000);
    };

    const handleBiometricAuth = async () => {
        setError('');
        if (!isHardwareSupported) {
             setError("Secure biometric hardware not detected on this device. Please use password.");
             return;
        }

        try {
            const challenge = new Uint8Array(32);
            window.crypto.getRandomValues(challenge);
            await navigator.credentials.get({
                publicKey: {
                    challenge,
                    rpId: window.location.hostname,
                    userVerification: "required",
                    timeout: 60000, 
                }
            });
            setShowBiometricScanner(true);
        } catch (err: any) {
            console.warn("Biometric authentication failed or cancelled", err);
            setError("Biometric authentication failed. Ensure your device security is enabled.");
        }
    };

    const handleBiometricComplete = () => {
        setShowBiometricScanner(false);
        onLogin(USER_PROFILE);
    };

    const handleMfaSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        // Strict check against the randomly generated code
        if (generatedOtp && mfaCode === generatedOtp) {
            setIsProcessing(true);
            setTimeout(() => {
                if (authenticatedUser) {
                    onLogin(authenticatedUser.profile);
                }
            }, 1000);
        } else {
            setError('Verification failed. The code entered is incorrect.');
        }
    };

    const renderCredentialsStep = () => (
        <div className="w-full animate-fade-in-up">
            <form onSubmit={handleLoginSubmit} className="space-y-6">
                <div className="space-y-4">
                    <div>
                        <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">User ID</label>
                        <input 
                            type="email" 
                            value={email}
                            onChange={(e) => { setEmail(e.target.value); setError(''); }}
                            className={`w-full bg-slate-800/50 border ${error ? 'border-red-500' : 'border-slate-700'} text-white p-4 rounded-xl focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all placeholder-slate-600`}
                            placeholder="Enter your email"
                            autoFocus
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Password</label>
                        <div className="relative">
                            <input 
                                type={showPassword ? "text" : "password"}
                                value={password}
                                onChange={(e) => { setPassword(e.target.value); setError(''); }}
                                className={`w-full bg-slate-800/50 border ${error ? 'border-red-500' : 'border-slate-700'} text-white p-4 rounded-xl focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all placeholder-slate-600`}
                                placeholder="Enter your password"
                            />
                            <button 
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300"
                            >
                                {showPassword ? <EyeSlashIcon className="w-5 h-5" /> : <EyeIcon className="w-5 h-5" />}
                            </button>
                        </div>
                    </div>
                </div>

                {error && (
                    <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/20 rounded-xl">
                        <ExclamationCircleIcon className="w-5 h-5 text-red-400" />
                        <p className="text-red-400 text-xs font-bold">{error}</p>
                    </div>
                )}

                <button 
                    type="submit" 
                    disabled={isProcessing}
                    className="w-full py-4 bg-primary hover:bg-primary-600 text-white rounded-xl font-bold shadow-lg shadow-primary/20 transition-all transform active:scale-[0.98] flex items-center justify-center gap-2 disabled:opacity-50"
                >
                    {isProcessing ? <SpinnerIcon className="w-5 h-5" /> : <LockClosedIcon className="w-5 h-5" />}
                    <span>Secure Sign In</span>
                </button>
            </form>

            <div className="my-6 flex items-center gap-4">
                <div className="h-px bg-white/10 flex-1"></div>
                <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Or Login With</span>
                <div className="h-px bg-white/10 flex-1"></div>
            </div>

            {isHardwareSupported ? (
                <button 
                    type="button" 
                    onClick={handleBiometricAuth}
                    className="w-full py-3 bg-white/5 hover:bg-white/10 border border-white/10 hover:border-primary/50 text-white rounded-xl font-bold transition-all flex items-center justify-center gap-3 group"
                >
                    <FaceIdIcon className="w-5 h-5 text-primary group-hover:scale-110 transition-transform" />
                    <span className="text-sm">Face ID / Passkey</span>
                </button>
            ) : (
                <div className="text-center p-3 bg-slate-800/50 rounded-xl border border-white/5">
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">Device Hardware Not Supported for Biometrics</p>
                </div>
            )}

            <div className="text-center pt-6">
                <p className="text-slate-400 text-sm">Don't have an account?</p>
                <button 
                    type="button" 
                    onClick={onStartCreateAccount}
                    className="text-primary font-bold hover:text-primary-400 transition-colors mt-1"
                >
                    Apply for Access
                </button>
            </div>
        </div>
    );

    const renderMfaStep = () => {
      const phone = authenticatedUser?.profile?.phone || `+1 (315) 915-${DEMO_PHONE_ENDING}`;
      return (
          <form onSubmit={handleMfaSubmit} className="space-y-8 w-full animate-fade-in-up">
               <div className="flex flex-col items-center">
                    <div className="p-4 bg-primary/20 rounded-full text-primary mb-4 ring-1 ring-primary/30 shadow-[0_0_15px_rgba(0,82,255,0.2)]">
                        <DevicePhoneMobileIcon className="w-10 h-10" />
                    </div>
                    <p className="text-center text-slate-300">
                        We sent a code to your secure device via <strong className="text-white">SMS</strong> (ending in {phone.slice(-4)}).
                    </p>
               </div>

               <div className="relative">
                    <input 
                        type="text" 
                        value={mfaCode}
                        onChange={(e) => { setMfaCode(e.target.value.replace(/\D/g, '').slice(0, 6)); setError(''); }}
                        className={`w-full bg-black/50 border ${error ? 'border-red-500' : 'border-slate-700'} text-white p-4 rounded-xl text-center text-3xl tracking-[0.5em] focus:ring-2 focus:ring-primary focus:border-transparent outline-none font-mono`}
                        placeholder="000000"
                        autoFocus
                    />
               </div>

               {error && (
                    <div className="flex items-center justify-center gap-2 p-3 bg-red-500/10 border border-red-500/20 rounded-xl">
                        <ExclamationCircleIcon className="w-4 h-4 text-red-400" />
                        <p className="text-red-400 text-xs font-bold">{error}</p>
                    </div>
               )}

               <button 
                    type="submit" 
                    disabled={isProcessing || mfaCode.length !== 6}
                    className="w-full py-4 bg-primary hover:bg-primary-600 text-white rounded-xl font-bold shadow-lg shadow-primary/20 transition-all transform active:scale-[0.98] flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {isProcessing ? <SpinnerIcon className="w-5 h-5" /> : <span>Verify Identity</span>}
                </button>

                <div className="flex justify-between items-center text-sm">
                    <button type="button" onClick={() => setStep('credentials')} className="text-slate-500 hover:text-slate-300">
                        Back to Login
                    </button>
                    <button 
                        type="button" 
                        onClick={handleResendMfa} 
                        disabled={isResending}
                        className="text-primary hover:text-primary-400 font-bold disabled:opacity-50"
                    >
                        {isResending ? 'Sending...' : 'Resend Code'}
                    </button>
                </div>
          </form>
      );
    };

    return (
        <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4 relative overflow-hidden">
            {showBiometricScanner && (
                <BiometricLoginScanner 
                    onComplete={handleBiometricComplete} 
                    onClose={() => setShowBiometricScanner(false)} 
                />
            )}

            <div className="absolute inset-0 z-0 bg-slate-900">
                {BACKGROUND_IMAGES.map((img, index) => (
                    <div 
                        key={index}
                        className={`absolute inset-0 transition-opacity duration-[2500ms] ease-in-out bg-cover bg-center ${index === bgIndex ? 'opacity-100 scale-100' : 'opacity-0 scale-105'}`}
                        style={{ backgroundImage: `url('${img}')` }}
                    >
                        <div className={`absolute inset-0 w-full h-full bg-inherit ${index === bgIndex ? 'animate-ken-burns' : ''}`}></div>
                    </div>
                ))}
            </div>

            <div className="absolute inset-0 z-[1] bg-gradient-to-b from-slate-900/60 via-slate-900/30 to-slate-900/80 pointer-events-none"></div>
            <div className="absolute inset-0 z-[1] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 mix-blend-overlay pointer-events-none"></div>

            <div className="w-full max-w-md relative z-20">
                <div className="text-center mb-10">
                    <div className="inline-block p-4 rounded-2xl bg-slate-800/50 border border-white/10 shadow-2xl backdrop-blur-xl mb-6">
                        <PremiumReservedBankLogo className="w-12 h-12" />
                    </div>
                    <h1 className="text-3xl font-bold text-white tracking-tight">Welcome Back</h1>
                    <p className="text-slate-400 mt-2">Access your First Pacific portfolio securely.</p>
                </div>

                <div className="bg-slate-900/50 backdrop-blur-xl border border-white/10 rounded-3xl p-8 shadow-2xl">
                    {step === 'credentials' ? renderCredentialsStep() : renderMfaStep()}
                </div>
            </div>
        </div>
    );
};

import { UserProfile, Transaction, Recipient, LoanApplication, LoanApplicationStatus, SavedSession } from '../types';
import { hashString } from '../utils/security';
import { USER_PROFILE, USER_PASSWORD, INITIAL_TRANSACTIONS, INITIAL_RECIPIENTS, INITIAL_LOAN_APPLICATIONS } from '../components/constants';
import { supabase } from './supabase';
import { validateSafeInput } from '../utils/validation';

// Database Keys
const DB_USERS_KEY = 'prb_users_v1';
const DB_SESSION_KEY = 'prb_session_v1';
const DB_TRANSACTIONS_KEY = 'prb_transactions_v1';
const DB_RECIPIENTS_KEY = 'prb_recipients_v1';
const DB_LOAN_APPLICATIONS_KEY = 'prb_loans_v1';

// ADDED export to fix type visibility issues that cause comparison errors in other files
export interface UserRecord {
    id: string;
    email: string;
    passwordHash: string;
    profile: UserProfile;
    createdAt: string;
    pinHash?: string;
}

const base64ToBlob = (base64: string): Blob => {
    try {
        const arr = base64.split(',');
        const mimeMatch = arr[0].match(/:(.*?);/);
        const mime = mimeMatch ? mimeMatch[1] : 'application/octet-stream';
        const bstr = atob(arr[1]);
        let n = bstr.length;
        const u8arr = new Uint8Array(n);
        while (n--) {
            u8arr[n] = bstr.charCodeAt(n);
        }
        return new Blob([u8arr], { type: mime });
    } catch (e) {
        console.warn('[DB] base64ToBlob conversion failed, using empty fallback.');
        return new Blob([], { type: 'application/octet-stream' });
    }
};

class DatabaseService {
    private users: Map<string, UserRecord> = new Map();
    private transactions: Map<string, Transaction> = new Map();
    private recipients: Map<string, Recipient> = new Map();
    private loanApplications: Map<string, LoanApplication> = new Map();
    private isInitialized = false;

    constructor() {
        this.init();
    }

    private async init() {
        try {
            // Load Users
            const storedUsers = localStorage.getItem(DB_USERS_KEY);
            if (storedUsers) {
                try {
                    const parsed = JSON.parse(storedUsers);
                    if (parsed && typeof parsed === 'object') {
                        Object.values(parsed).forEach((u: any) => {
                            if (u && u.profile) {
                                if (u.profile.lastLogin?.date) {
                                    u.profile.lastLogin.date = new Date(u.profile.lastLogin.date);
                                }
                                this.users.set(u.email, u);
                            }
                        });
                    }
                } catch (e) {
                    console.warn('[DB] User Store Corrupt. Resetting.');
                    localStorage.removeItem(DB_USERS_KEY);
                }
            }

            await this.seedInitialUsers();

            // Load Transactions
            const storedTransactions = localStorage.getItem(DB_TRANSACTIONS_KEY);
            if (storedTransactions) {
                try {
                    const parsedTx = JSON.parse(storedTransactions);
                    if (Array.isArray(parsedTx)) {
                        parsedTx.forEach((tx: Transaction) => {
                            tx.estimatedArrival = new Date(tx.estimatedArrival);
                            if (tx.statusTimestamps) {
                                Object.keys(tx.statusTimestamps).forEach(key => {
                                    // @ts-ignore
                                    tx.statusTimestamps[key] = new Date(tx.statusTimestamps[key]);
                                });
                            }
                            this.transactions.set(tx.id, tx);
                        });
                    }
                } catch (e) {
                    console.warn('[DB] Transaction Ledger Corrupt. Resetting.');
                    localStorage.removeItem(DB_TRANSACTIONS_KEY);
                }
            }

            if (this.transactions.size === 0) {
                INITIAL_TRANSACTIONS.forEach(tx => this.transactions.set(tx.id, tx));
                this.persistTransactions();
            }

            // Load Recipients
            const storedRecipients = localStorage.getItem(DB_RECIPIENTS_KEY);
            if (storedRecipients) {
                try {
                    const parsedRec = JSON.parse(storedRecipients);
                    if (Array.isArray(parsedRec)) {
                        parsedRec.forEach((rec: Recipient) => {
                            this.recipients.set(rec.id, rec);
                        });
                    }
                } catch (e) {
                     console.warn('[DB] Recipient Map Corrupt. Resetting.');
                     localStorage.removeItem(DB_RECIPIENTS_KEY);
                }
            }

            if (this.recipients.size === 0) {
                INITIAL_RECIPIENTS.forEach(rec => this.recipients.set(rec.id, rec));
                this.persistRecipients();
            }

            // Load Loan Apps
            const storedLoanApps = localStorage.getItem(DB_LOAN_APPLICATIONS_KEY);
            if (storedLoanApps) {
                try {
                    const parsedApps = JSON.parse(storedLoanApps);
                    if (Array.isArray(parsedApps)) {
                        parsedApps.forEach((app: LoanApplication) => {
                            app.submittedDate = new Date(app.submittedDate);
                            this.loanApplications.set(app.id, app);
                        });
                    }
                } catch (e) {
                     console.warn('[DB] Credit Requests Corrupt. Resetting.');
                     localStorage.removeItem(DB_LOAN_APPLICATIONS_KEY);
                }
            }

            if (this.loanApplications.size === 0) {
                INITIAL_LOAN_APPLICATIONS.forEach(app => this.loanApplications.set(app.id, app));
                this.persistLoanApplications();
            }

            this.isInitialized = true;
            console.log('[DB] Storage Initialized.');
        } catch (e) {
            console.warn('[DB] Initialization failure.', e);
            this.isInitialized = true;
        }
    }

    private async seedInitialUsers() {
        try {
            const defaultPasswordHash = await hashString(USER_PASSWORD);
            const defaultUser: UserRecord = {
                id: 'usr_default_001',
                email: USER_PROFILE.email,
                passwordHash: defaultPasswordHash,
                profile: USER_PROFILE,
                createdAt: new Date().toISOString()
            };
            if (this.users.size === 0) {
                this.users.set(defaultUser.email, defaultUser);
                this.persistUsers();
            }
        } catch (e) {
            console.warn('[DB] Seeding failed', e);
        }
    }

    private async persistUsers() {
        try {
            const obj = Object.fromEntries(this.users);
            localStorage.setItem(DB_USERS_KEY, JSON.stringify(obj));
        } catch (e) {
