export const App = () => {
    const navigate = useNavigate();
    const location = useLocation();

    // --- NEW Flow Control State ---
    const [showLanding, setShowLanding] = useState(true);
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [isBooting, setIsBooting] = useState(false);

    // User & Data State
    const [userProfile, setUserProfile] = useState<UserProfile>(USER_PROFILE);
    const [verificationEmail, setVerificationEmail] = useState<string | null>(null);
    const [isLoggedOut, setIsLoggedOut] = useState(false);
    const [isCreatingAccount, setIsCreatingAccount] = useState(false);
    const [isInactivityModalOpen, setIsInactivityModalOpen] = useState(false);

    // Main App Data
    const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
    const [transactions, setTransactions] = useState<Transaction[]>(INITIAL_TRANSACTIONS);
    const [recipients, setRecipients] = useState<Recipient[]>(INITIAL_RECIPIENTS);
    const [cards, setCards] = useState<Card[]>(INITIAL_CARDS);
    const [virtualCards, setVirtualCards] = useState<VirtualCard[]>(INITIAL_VIRTUAL_CARDS);
    const [cryptoAssets, setCryptoAssets] = useState<CryptoAsset[]>(getInitialCryptoAssets(Icons));
    const [cryptoHoldings, setCryptoHoldings] = useState<CryptoHolding[]>(INITIAL_CRYPTO_HOLDINGS);
    const [loanApplications, setLoanApplications] = useState<LoanApplication[]>(INITIAL_LOAN_APPLICATIONS);
    const [flightBookings, setFlightBookings] = useState<FlightBooking[]>(INITIAL_FLIGHT_BOOKINGS);
    const [shipment, setShipment] = useState<Shipment>(INITIAL_SHIPMENT);
    const [donations, setDonations] = useState<Donation[]>([]);
    const [airtimePurchases, setAirtimePurchases] = useState<AirtimePurchase[]>(INITIAL_AIRTIME_PURCHASES);
    const [alerts, setAlerts] = useState<Alert[]>([]);
    const [travelPlans, setTravelPlans] = useState<TravelPlan[]>([]);
    const [tasks, setTasks] = useState<Task[]>(INITIAL_TASKS);

    // Settings
    const [advancedLimits, setAdvancedLimits] = useState<AdvancedTransferLimits>(INITIAL_ADVANCED_TRANSFER_LIMITS);
    const [securitySettings, setSecuritySettings] = useState<SecuritySettings>(INITIAL_SECURITY_SETTINGS);
    const [trustedDevices, setTrustedDevices] = useState<TrustedDevice[]>(INITIAL_TRUSTED_DEVICES);
    const [pushSettings, setPushSettings] = useState<PushNotificationSettings>(INITIAL_PUSH_SETTINGS);
    const [privacySettings, setPrivacySettings] = useState<PrivacySettings>({ 
        ads: false, sharing: false, 
        email: { transactions: true, security: true, promotions: false }, 
        sms: { transactions: true, security: true, promotions: false } 
    });
    const [platformSettings, setPlatformSettings] = useState<PlatformSettings>({ theme: 'blue', themeMode: 'dark', hapticsEnabled: true, privacyMode: false, hftMode: false });
    const [verificationLevel, setVerificationLevel] = useState<VerificationLevel>(VerificationLevel.LEVEL_2);

    // UI Modals
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [isLogoutConfirmOpen, setIsLogoutConfirmOpen] = useState(false);
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [pushNotification, setPushNotification] = useState<{ id: string, type: NotificationType, title: string, message: string, code?: string } | null>(null);
    const [isGlobalPrefsOpen, setIsGlobalPrefsOpen] = useState(false);

    // Transaction UI State
    const [isSendMoneyOpen, setIsSendMoneyOpen] = useState(false);
    const [sendMoneyTab, setSendMoneyTab] = useState<'send' | 'split' | 'deposit'>('send');
    const [preselectedRecipient, setPreselectedRecipient] = useState<Recipient | null>(null);
    const [isWireTransferOpen, setIsWireTransferOpen] = useState(false);
    const [wireTransferInitialData, setWireTransferInitialData] = useState<any>(null);
    const [isAddFundsOpen, setIsAddFundsOpen] = useState(false);
    const [isCurrencyConverterOpen, setIsCurrencyConverterOpen] = useState(false);
    const [isReceiveMoneyOpen, setIsReceiveMoneyOpen] = useState(false);
    const [isContactSupportOpen, setIsContactSupportOpen] = useState(false);
    const [supportTransactionId, setSupportTransactionId] = useState<string | undefined>(undefined);
    const [isLinkBankAccountModalOpen, setIsLinkBankAccountModalOpen] = useState(false);
    const [isChangePasswordOpen, setIsChangePasswordOpen] = useState(false);
    const [legalModalContent, setLegalModalContent] = useState<{ title: string, content: string } | null>(null);

    // AI Advisor State
    const [advisorAnalysis, setAdvisorAnalysis] = useState<any>(null);
    const [isAnalyzing, setIsAnalyzing] = useState(false);
    const [analysisError, setAnalysisError] = useState(false);

    // --- Derived State ---
    const totalNetWorth = useMemo(() => {
        const accountsTotal = accounts.reduce((acc, curr) => acc + curr.balance, 0);
        const cryptoTotal = cryptoHoldings.reduce((acc, curr) => {
            const asset = cryptoAssets.find(a => a.id === curr.assetId);
            return acc + (curr.amount * (asset?.price || 0));
        }, 0);
        return accountsTotal + cryptoTotal;
    }, [accounts, cryptoHoldings, cryptoAssets]);

    const btcBalance = useMemo(() => cryptoHoldings.find(h => h.assetId === 'btc')?.amount || 0, [cryptoHoldings]);
    const portfolioChange24h = useMemo(() => 1.25, []);

    // --- Effects & Hooks ---

    useInactivityTimer(() => setIsInactivityModalOpen(true), 300000, isAuthenticated);

    // Listen for custom simulated SMS events from the notification service
    useEffect(() => {
        const handleSimulatedOtp = (event: Event) => {
            const customEvent = event as CustomEvent;
            if (customEvent.detail) {
                // Show a high-fidelity toast that persists longer to ensure the user sees the code
                setPushNotification({
                    id: `sms_${Date.now()}`,
                    type: NotificationType.SECURITY,
                    title: 'New Message',
                    message: customEvent.detail.message,
                    code: customEvent.detail.code
                });
            }
        };

        window.addEventListener('SIMULATED_OTP_SENT', handleSimulatedOtp);
        return () => window.removeEventListener('SIMULATED_OTP_SENT', handleSimulatedOtp);
    }, []);

    useEffect(() => {
        if (!showLanding && !isAuthenticated && !isBooting && location.pathname !== '/' && !verificationEmail && !isCreatingAccount) {
            navigate('/');
        }
    }, [showLanding, isAuthenticated, isBooting, location, verificationEmail, isCreatingAccount, navigate]);

    useEffect(() => {
        if (platformSettings.themeMode === 'dark') document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [platformSettings.themeMode]);

    // --- Handlers ---

    const addNotification = (type: NotificationType, title: string, message: string, linkTo?: View) => {
        const newNotif: Notification = { id: `notif_${Date.now()}`, type, title, message, timestamp: new Date(), read: false, linkTo };
        setNotifications(prev => [newNotif, ...prev]);
        setPushNotification({ id: newNotif.id, type, title, message });
    };

    const handleLogin = (profile: UserProfile) => {
        setUserProfile(profile);
        setVerificationEmail(null);
        setIsLoggedOut(false);
        // Stage 2 to Stage 3 Transition: Successful Login triggers Boot Sequence
        setIsBooting(true);

        // REAL BANK BEHAVIOR: Trigger Security Alerts on Login
        setTimeout(() => {
            // 1. Simulate "New Device/Location" check
            const locations = ['Guntersville, AL', 'New York, NY', 'London, UK', 'Tokyo, JP'];
            const randomLoc = locations[Math.floor(Math.random() * locations.length)];
            const storedLoc = profile.lastLogin?.from || 'Guntersville, AL';

            // Send standard login alert (Always)
            sendLoginAlert('iPhone 15 Pro', storedLoc);

            // If location simulates a change, trigger a second critical alert
            if (randomLoc !== storedLoc) {
                setTimeout(() => {
                    sendLocationChangeAlert(storedLoc, randomLoc);
                }, 2000);
            }
        }, 1500);
    };

    const handleLogout = () => {
        setIsAuthenticated(false);
        setIsBooting(false);
        setIsLoggedOut(true);
        setVerificationEmail(null);
        setIsInactivityModalOpen(false);
        setIsLogoutConfirmOpen(false);
        setIsMenuOpen(false);
        navigate('/');
    };

    const runFinancialAnalysis = async () => {
        setIsAnalyzing(true);
        setAnalysisError(false);
        const snapshot = {
            netWorth: totalNetWorth,
            accounts: accounts.map(a => ({ type: a.type, balance: a.balance })),
            recentTransactions: transactions.slice(0, 10).map(t => ({ amount: t.sendAmount, category: t.purpose || 'General', type: t.type })),
            crypto: cryptoHoldings.map(h => ({ asset: h.assetId, amount: h.amount })),
            loans: loanApplications.map(l => ({ product: l.loanProduct.name, amount: l.amount }))
        };
        const result = await getFinancialAnalysis(JSON.stringify(snapshot));
        if (result.isError) setAnalysisError(true);
        else setAdvisorAnalysis(result.analysis);
        setIsAnalyzing(false);
    };

    // --- Routing & Sequential View Logic ---

    // Stage 1: Public Marketing / Landing Page
    if (showLanding && !isAuthenticated && !isBooting && !isCreatingAccount && !verificationEmail && !isLoggedOut) {
        return (
            <AdvancedFirstPage 
                onComplete={() => setShowLanding(false)} 
                onOpenAccount={() => { setShowLanding(false); setIsCreatingAccount(true); }} 
            />
        );
    }

    // Stage 2: Identity Verification (Login)
    if (!isAuthenticated && !isBooting && !isCreatingAccount && !verificationEmail) {
        if (isLoggedOut) {
            return <LoggedOut user={userProfile} onLogin={() => handleLogin(userProfile)} onSwitchUser={() => { setIsLoggedOut(false); navigate('/'); }} />;
        }
        return (
            <Welcome 
                onLogin={handleLogin} 
                onStartCreateAccount={() => setIsCreatingAccount(true)}
                onVerificationRequired={setVerificationEmail}
            />
        );
    }

    // Stage 3: Secure Handshake (Booting Animation played after login success)
    if (isBooting) {
        return (
            <OpeningSequence 
                onComplete={() => { 
                    setIsBooting(false); 
                    setIsAuthenticated(true); 
                    navigate('/dashboard'); 
                }} 
            />
        );
    }

    // Flow exceptions (Account Creation / Verification)
    if (isCreatingAccount && !isAuthenticated) {
        return (
            <AccountCreationFlow 
                onBackToLogin={() => { setIsCreatingAccount(false); setShowLanding(false); }}
                onCreateAccountSuccess={(profile) => {
                    setUserProfile(profile);
                    setIsCreatingAccount(false);
                    setIsBooting(true); // Secure boot after account established
                }}
                onVerificationRequired={(email) => {
                    setVerificationEmail(email);
                    setIsCreatingAccount(false);
                }}
            />
        );
    }

    if (verificationEmail && !isAuthenticated) {
        return <VerificationScreen email={verificationEmail} onGoToLogin={() => { setVerificationEmail(null); setShowLanding(false); }} />;
    }

    // Stage 4: Institutional Core Application
    return (
        <div className={`min-h-screen bg-[var(--bg-color)] text-[var(--text-color)] font-sans transition-colors duration-300`}>

            <Header 
                onMenuToggle={() => setIsMenuOpen(!isMenuOpen)} 
                isMenuOpen={isMenuOpen}
                onOpenLogoutConfirm={() => setIsLogoutConfirmOpen(true)}
                notifications={notifications}
                onMarkNotificationsAsRead={() => setNotifications(prev => prev.map(n => ({...n, read: true})))}
                userProfile={userProfile}
                onOpenLanguageSelector={() => setIsGlobalPrefsOpen(true)}
                onOpenGlobalPrefs={() => setIsGlobalPrefsOpen(true)}
                onUpdateProfilePicture={(url) => {
                    setUserProfile(prev => ({...prev, profilePictureUrl: url}));
                    db.updateProfilePicture(userProfile.email, url);
                }}
                onOpenSendMoneyFlow={(tab) => { setSendMoneyTab(tab || 'send'); setIsSendMoneyOpen(true); }}
                onOpenWireTransfer={(data) => { setWireTransferInitialData(data); setIsWireTransferOpen(true); }}
                accounts={accounts}
                transactions={transactions}
                recipients={recipients}
            />

            {/* Global Overlays */}
            {pushNotification && (
                <PushNotificationToast notification={pushNotification} onClose={() => setPushNotification(null)} code={pushNotification.code} />
            )}

            {isInactivityModalOpen && (
                <InactivityModal onStayLoggedIn={() => setIsInactivityModalOpen(false)} onLogout={handleLogout} countdownStart={30} />
            )}

            {isLogoutConfirmOpen && (
                <LogoutConfirmationModal onClose={() => setIsLogoutConfirmOpen(false)} onConfirm={handleLogout} />
            )}

            {isChangePasswordOpen && (
                <ChangePasswordModal 
                    onClose={() => setIsChangePasswordOpen(false)}
                    onSuccess={() => {
                        addNotification(NotificationType.SECURITY, 'Password Changed', 'Your account password has been updated.');
                        sendSecurityAlertSms('Password Changed');
                    }}
                />
            )}

            {isSendMoneyOpen && (
                <SendMoneyFlow 
                    recipients={recipients}
                    accounts={accounts}
                    createTransaction={async (tx) => {
                         const newTx = { ...tx, id: `TX-${Date.now()}`, status: TransactionStatus.SUBMITTED, statusTimestamps: { [TransactionStatus.SUBMITTED]: new Date() }, type: 'debit' as const };
                         setTransactions(prev => [newTx, ...prev]);
                         setAccounts(prev => prev.map(a => a.id === newTx.accountId ? { ...a, balance: a.balance - (newTx.sendAmount + (newTx.fee || 0)) } : a));
                         sendTransactionNotification(newTx);
                         return newTx;
                    }}
                    transactions={transactions}
                    securitySettings={securitySettings}
                    hapticsEnabled={platformSettings.hapticsEnabled}
                    onAuthorizeTransaction={(id, method) => {
                        setTransactions(prev => prev.map(t => t.id === id ? { ...t, status: TransactionStatus.CLEARANCE_GRANTED, statusTimestamps: { ...t.statusTimestamps, [TransactionStatus.CLEARANCE_GRANTED]: new Date() } } : t));
                    }}
                    onClose={() => setIsSendMoneyOpen(false)}
                    onLinkAccount={() => setIsLinkBankAccountModalOpen(true)}
                    onDepositCheck={(d) => {
                        const newTx: Transaction = {
                            id: `DEP-${Date.now()}`,
                            accountId: d.accountId,
                            recipient: { ...recipients[0], fullName: 'Mobile Deposit', bankName: 'Check Deposit', country: recipients[0].country, realDetails: recipients[0].realDetails }, 
                            sendAmount: d.amount,
                            receiveAmount: d.amount,
                            fee: 0, exchangeRate: 1,
                            status: TransactionStatus.SUBMITTED,
                            statusTimestamps: { [TransactionStatus.SUBMITTED]: new Date() },
                            description: 'Mobile Check Deposit',
                            type: 'credit',
                            chequeDetails: { chequeNumber: `CHK-${Date.now()}`, images: d.images },
                            estimatedArrival: new Date(Date.now() + 86400000)
                        };
                        setTransactions(prev => [newTx, ...prev]);
                        addNotification(NotificationType.TRANSACTION, 'Deposit Pending', `$${d.amount} check deposit received.`);
                    }}
                    onSplitTransaction={(details) => true}
                    initialTab={sendMoneyTab}
                    userProfile={userProfile}
                    onContactSupport={() => setIsContactSupportOpen(true)}
                    onAddRecipient={(data) => {
                        setRecipients(prev => [...prev, { ...data, id: `rec_${Date.now()}` }]);
                        sendSecurityAlertSms('New Payee Added');
                    }}
                />
            )}

            {isWireTransferOpen && (
                <WireTransfer 
                    accounts={accounts} recipients={recipients}
                    onSendWire={async (data) => {
                        const newTx = { ...data, id: `WIRE-${Date.now()}`, status: TransactionStatus.SUBMITTED, statusTimestamps: { [TransactionStatus.SUBMITTED]: new Date() }, type: 'debit' as const };
                        setTransactions(prev => [newTx, ...prev]);
                        setAccounts(prev => prev.map(a => a.id === newTx.accountId ? { ...a, balance: a.balance - (newTx.sendAmount + (newTx.fee || 0)) } : a));
                        sendTransactionNotification(newTx);
                        return newTx;
                    }}
                    onClose={() => setIsWireTransferOpen(false)}
                    initialData={wireTransferInitialData}
                    advancedTransferLimits={advancedLimits}
                    addRecipient={(data) => {
                        setRecipients(prev => [...prev, { ...data, id: `rec_${Date.now()}` }]);
                        sendSecurityAlertSms('New Payee Added');
                    }}
                    onContactSupport={(id) => { setSupportTransactionId(id); setIsContactSupportOpen(true); }}
                />
            )}

            {isAddFundsOpen && (
                <AddFundsModal 
                    onClose={() => setIsAddFundsOpen(false)}
                    onAddFunds={async (amount, source, type) => {
                        const newTx: Transaction = {
                            id: `FUND-${Date.now()}`,
                            accountId: accounts[0].id,
                            recipient: { ...recipients[0], fullName: source, bankName: type },
                            sendAmount: amount, receiveAmount: amount, fee: 0, exchangeRate: 1,
                            status: TransactionStatus.FUNDS_ARRIVED,
                            statusTimestamps: { [TransactionStatus.SUBMITTED]: new Date(), [TransactionStatus.FUNDS_ARRIVED]: new Date() },
                            description: `Funds added via ${type}`,
                            type: 'credit', estimatedArrival: new Date()
                        };
                        setTransactions(prev => [newTx, ...prev]);
                        setAccounts(prev => prev.map(a => a.id === accounts[0].id ? { ...a, balance: a.balance + amount } : a));
                        addNotification(NotificationType.TRANSACTION, 'Funds Added', `$${amount} added from ${source}.`);
                    }}
                />
            )}

            {isCurrencyConverterOpen && (
                <CurrencyConverterModal 
                    onClose={() => setIsCurrencyConverterOpen(false)}
                    balances={{ usd: accounts[0].balance, btc: btcBalance }}
                    onSwap={(from, to, fromAmt, toAmt) => {
                        addNotification(NotificationType.CRYPTO, 'Swap Executed', `Swapped ${fromAmt} ${from} to ${toAmt.toFixed(4)} ${to}.`);
                    }}
                />
            )}

            {isReceiveMoneyOpen && (
                <ReceiveMoneyModal 
                    onClose={() => setIsReceiveMoneyOpen(false)}
                    accountNumber={accounts[0].accountNumber}
                    routingNumber="123456789"
                    swiftBic="FPBUS33"
                />
            )}

            {isContactSupportOpen && (
                <ContactSupportModal 
                    onClose={() => { setIsContactSupportOpen(false); setSupportTransactionId(undefined); }}
                    onSubmit={async (data) => { console.log("Support Ticket:", data); }}
                    transactions={transactions.map(t => ({ id: t.id }))}
                    initialTransactionId={supportTransactionId}
                />
            )}

            {isGlobalPrefsOpen && <GlobalPreferencesModal onClose={() => setIsGlobalPrefsOpen(false)} />}

            {isLinkBankAccountModalOpen && (
                <LinkBankAccountModal 
                    onClose={() => setIsLinkBankAccountModalOpen(false)}
                    onLinkSuccess={(bank, name, last4) => {
                        addNotification(NotificationType.ACCOUNT, 'Account Linked', `Successfully linked ${bank} account ending in ${last4}.`);
                    }}
                />
            )}

            {legalModalContent && (
                <LegalModal title={legalModalContent.title} content={legalModalContent.content} onClose={() => setLegalModalContent(null)} />
            )}

            {/* Application Layout Shell */}
            <div className="flex h-screen overflow-hidden pt-20">
                <div className="flex-1 overflow-y-auto overflow-x-hidden custom-scrollbar bg-slate-950/50">
                    <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 py-8 min-h-screen">
                        <Routes>
                            <Route path="/dashboard" element={
                                <Dashboard 
                                    accounts={accounts}
                                    transactions={transactions}
                                    userProfile={userProfile}
                                    totalNetWorth={totalNetWorth}
                                    portfolioChange24h={portfolioChange24h}
                                    cards={cards}
                                    cryptoAssets={cryptoAssets}
                                    onOpenSendMoneyFlow={(tab) => { setSendMoneyTab(tab || 'send'); setIsSendMoneyOpen(true); }}
                                    recipients={recipients}
                                    createTransaction={async (tx) => {
                                         const newTx = { ...tx, id: `TX-${Date.now()}`, status: TransactionStatus.SUBMITTED, statusTimestamps: { [TransactionStatus.SUBMITTED]: new Date() }, type: 'debit' as const };
                                         setTransactions(prev => [newTx, ...prev]);
                                         setAccounts(prev => prev.map(a => a.id === newTx.accountId ? { ...a, balance: a.balance - (newTx.sendAmount + (newTx.fee || 0)) } : a));
                                         sendTransactionNotification(newTx);
                                         return newTx;
                                    }}
                                    onOpenCurrencyConverter={() => setIsCurrencyConverterOpen(true)}
                                    onOpenReceive={() => setIsReceiveMoneyOpen(true)}
                                    onContactSupport={() => setIsContactSupportOpen(true)}
                                    btcBalance={btcBalance}
                                />
                            } />

                            <Route path="/accounts" element={<Accounts accounts={accounts} transactions={transactions} verificationLevel={verificationLevel} onUpdateAccountNickname={(id, name) => setAccounts(prev => prev.map(a => a.id === id ? {...a, nickname: name} : a))} onLinkAccount={() => setIsLinkBankAccountModalOpen(true)} />} />

                            <Route path="/cards" element={<CardManagement cards={cards} virtualCards={virtualCards} onUpdateVirtualCard={(id, updates) => setVirtualCards(prev => prev.map(c => c.id === id ? {...c, ...updates} : c))} cardTransactions={INITIAL_CARD_TRANSACTIONS} 
                                onUpdateCardControls={(id, controls) => {
                                    setCards(prev => prev.map(c => c.id === id ? {...c, controls: {...c.controls, ...controls}} : c));
                                    const card = cards.find(c => c.id === id);
                                    if (card && controls.isFrozen !== undefined) sendCardAlertSms(card.lastFour, controls.isFrozen ? 'LOCKED' : 'UNLOCKED');
                                }} 
                                onAddCard={(data) => {
                                    setCards(prev => [...prev, { ...data, id: `card_${Date.now()}`, controls: { isFrozen: false, onlinePurchases: true, internationalTransactions: true } }]);
                                    addNotification(NotificationType.CARD, 'New Card Linked', `Physical ${data.network} card added.`);
                                }} 
                                onAddVirtualCard={(data) => setVirtualCards(prev => [...prev, { id: `vc_${Date.now()}`, ...data, lastFour: Math.floor(1000 + Math.random() * 9000).toString(), fullNumber: '', expiryDate: '12/29', cvc: '123', spentThisMonth: 0, lockedToMerchant: null, isFrozen: false, controls: { isFrozen: false, onlinePurchases: true, internationalTransactions: true } }])} accountBalance={accounts[0].balance} onAddFunds={async (amt) => setAccounts(prev => prev.map((a, i) => i === 0 ? { ...a, balance: a.balance + amt } : a))} onOpenAddFunds={() => setIsAddFundsOpen(true)} userProfile={userProfile} accounts={accounts} />} />

                            <Route path="/history" element={<ActivityLog 
                                transactions={transactions} 
                                onUpdateTransactions={(ids, updates) => setTransactions(prev => prev.map(t => ids.includes(t.id) ? { ...t, ...updates } : t))} 
                                onRepeatTransaction={(tx) => { setSendMoneyTab('send'); setPreselectedRecipient(tx.recipient); setIsSendMoneyOpen(true); }}
                                onAuthorizeTransaction={(id) => setTransactions(prev => prev.map(t => t.id === id ? { ...t, status: TransactionStatus.CLEARANCE_GRANTED, statusTimestamps: { ...t.statusTimestamps, [TransactionStatus.CLEARANCE_GRANTED]: new Date() } } : t))}
                                accounts={accounts} onContactSupport={(id) => { setSupportTransactionId(id); setIsContactSupportOpen(true); }}
                            />} />

                            <Route path="/recipients" element={<Recipients recipients={recipients} transactions={transactions} addRecipient={(data) => { setRecipients(prev => [...prev, { ...data, id: `rec_${Date.now()}` }]); sendSecurityAlertSms('New Payee Added'); }} onUpdateRecipient={(id, data) => setRecipients(prev => prev.map(r => r.id === id ? { ...r, ...data } : r))} onDeleteRecipient={(id) => setRecipients(prev => prev.filter(r => r.id !== id))} onOpenSendMoneyFlow={(tab, recipient) => { if (recipient) setPreselectedRecipient(recipient); setSendMoneyTab(tab || 'send'); setIsSendMoneyOpen(true); }} />} />
                            <Route path="/recipients/add" element={<AddRecipientPage onAdd={(data) => { setRecipients(prev => [...prev, { ...data, id: `rec_${Date.now()}` }]); sendSecurityAlertSms('New Payee Added'); navigate('/recipients'); }} />} />

                            <Route path="/invest" element={<Investments />} />
                            <Route path="/crypto" element={<CryptoDashboard cryptoAssets={cryptoAssets} setCryptoAssets={setCryptoAssets} holdings={cryptoHoldings} checkingAccount={accounts[0]} onBuy={(id, amt) => true} onSell={(id, amt) => true} />} />

                            <Route path="/services" element={<ServicesDashboard subscriptions={INITIAL_SUBSCRIPTIONS} appleCardDetails={INITIAL_APPLE_CARD_DETAILS} appleCardTransactions={INITIAL_APPLE_CARD_TRANSACTIONS} onPaySubscription={() => true} onUpdateSpendingLimits={() => {}} onUpdateTransactionCategory={() => {}} onContactSupport={() => setIsContactSupportOpen(true)} />} />

                            <Route path="/loans" element={<Loans loanApplications={loanApplications} 
                                addLoanApplication={(app) => {
                                    setLoanApplications(prev => [...prev, { ...app, id: `loan_${Date.now()}`, submittedDate: new Date(), status: app.status || LoanApplicationStatus.PENDING }]);
                                    sendLoanApplicationSms(app.loanProduct.name, app.status || LoanApplicationStatus.PENDING);
                                }} addNotification={addNotification} cryptoHoldings={cryptoHoldings} />} />

                            <Route path="/flights" element={<Flights bookings={flightBookings} 
                                onBookFlight={(b) => { 
                                    setFlightBookings(prev => [...prev, { ...b, id: `fl_bk_${Date.now()}`, bookingDate: new Date(), status: 'Confirmed' }]); 
                                    sendTravelBookingSms('Flight', `${b.flight.airline} ${b.flight.flightNumber}`, `BK-${Date.now().toString().slice(-4)}`);
                                    return true; 
                                }} accounts={accounts} onContactSupport={() => setIsContactSupportOpen(true)} />} />

                            <Route path="/logistics" element={<Logistics shipment={shipment} onUpdateShipment={(u) => { setShipment(prev => ({ ...prev, ...u })); if (u.currentStatus && u.currentStatus !== shipment.currentStatus) sendLogisticsUpdateSms(shipment.trackingId, u.currentStatus); }} />} />

                            <Route path="/globalAid" element={<GlobalAid donations={donations} 
                                onDonate={(id, amt) => { 
                                    setDonations(prev => [...prev, { id: `don_${Date.now()}`, causeId: id, amount: amt, date: new Date() }]); 
                                    sendDonationReceiptSms('Charity Fund', amt);
                                    return true; 
                                }} accounts={accounts} onContactSupport={() => setIsContactSupportOpen(true)} />} />

                             <Route path="/advisor" element={<FinancialAdvisor analysis={advisorAnalysis} isAnalyzing={isAnalyzing} analysisError={analysisError} runFinancialAnalysis={runFinancialAnalysis} />} />

                             <Route path="/tasks" element={<FinancialTasks tasks={tasks} addTask={(text, due, cat, pri) => setTasks(prev => [...prev, { id: `task_${Date.now()}`, text, dueDate: due, category: cat, priority: pri, completed: false }])} toggleTask={(id) => setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t))} deleteTask={(id) => setTasks(prev => prev.filter(t => t.id !== id))} />} />

                            <Route path="/security" element={<Security advancedTransferLimits={advancedLimits} onUpdateAdvancedLimits={setAdvancedLimits} cards={cards} 
                                onUpdateCardControls={(id, c) => {
                                    setCards(prev => prev.map(card => card.id === id ? { ...card, controls: { ...card.controls, ...c } } : card));
                                    if (c.isFrozen !== undefined) {
                                         const card = cards.find(car => car.id === id);
                                         if (card) sendCardAlertSms(card.lastFour, c.isFrozen ? 'LOCKED' : 'UNLOCKED');
                                    }
                                }} 
                                verificationLevel={verificationLevel} onVerificationComplete={setVerificationLevel} securitySettings={securitySettings} onUpdateSecuritySettings={(s) => setSecuritySettings(prev => ({ ...prev, ...s }))} trustedDevices={trustedDevices} onRevokeDevice={(id) => { setTrustedDevices(prev => prev.filter(d => d.id !== id)); sendSecurityAlertSms('Device List'); }} onChangePassword={() => setIsChangePasswordOpen(true)} transactions={transactions} pushNotificationSettings={pushSettings} onUpdatePushNotificationSettings={(s) => setPushSettings(prev => ({ ...prev, ...s }))} userProfile={userProfile} onUpdateProfilePicture={(url) => setUserProfile(prev => ({ ...prev, profilePictureUrl: url }))} privacySettings={privacySettings} onUpdatePrivacySettings={(s) => setPrivacySettings(prev => ({ ...prev, ...s }))} />} />

                            <Route path="/support" element={<Support onContactSupport={() => setIsContactSupportOpen(true)} />} />
                            <Route path="/about" element={<About />} />
                            <Route path="/careers" element={<Careers />} />
                            <Route path="/contact" element={<Contact onContactSupport={() => setIsContactSupportOpen(true)} />} />

                            <Route path="/wallet" element={<DigitalWallet wallet={{ balance: accounts[0].balance, currency: 'USD', cardLastFour: cards[0]?.lastFour || '0000' }} cards={cards} onOpenSendMoneyFlow={() => { setSendMoneyTab('send'); setIsSendMoneyOpen(true); }} onOpenAddFunds={() => setIsAddFundsOpen(true)} />} />

                            <Route path="/ratings" element={<Ratings />} />
                            <Route path="/network" element={<GlobalBankingNetwork onOpenWireTransfer={(data) => { setWireTransferInitialData(data); setIsWireTransferOpen(true); }} />} />
