                            <Route path="/checkin" element={<TravelCheckIn travelPlans={travelPlans} addTravelPlan={(c, s, e) => setTravelPlans(prev => [...prev, { id: `tp_${Date.now()}`, country: c, startDate: s, endDate: e, status: TravelPlanStatus.UPCOMING }])} />} />
                            <Route path="/platform" element={<PlatformFeatures settings={platformSettings} onUpdateSettings={(s) => setPlatformSettings(prev => ({...prev, ...s}))} />} />
                            <Route path="/utilities" element={<ServicesDashboard subscriptions={INITIAL_SUBSCRIPTIONS} appleCardDetails={INITIAL_APPLE_CARD_DETAILS} appleCardTransactions={INITIAL_APPLE_CARD_TRANSACTIONS} onPaySubscription={() => true} onUpdateSpendingLimits={() => {}} onUpdateTransactionCategory={() => {}} onContactSupport={() => setIsContactSupportOpen(true)} />} />
                            <Route path="/integrations" element={<ServicesDashboard subscriptions={INITIAL_SUBSCRIPTIONS} appleCardDetails={INITIAL_APPLE_CARD_DETAILS} appleCardTransactions={INITIAL_APPLE_CARD_TRANSACTIONS} onPaySubscription={() => true} onUpdateSpendingLimits={() => {}} onUpdateTransactionCategory={() => {}} onContactSupport={() => setIsContactSupportOpen(true)} />} />

                            <Route path="*" element={<Navigate to="/dashboard" replace />} />
                        </Routes>
                        <div className="h-20 lg:hidden"></div>
                    </div>
                </div>
            </div>

            <Footer onOpenSendMoneyFlow={(tab) => { setSendMoneyTab(tab || 'send'); setIsSendMoneyOpen(true); }} openLegalModal={(t, c) => setLegalModalContent({title: t, content: c})} />

            <MobileBottomNav onOpenSendMoneyFlow={() => { setSendMoneyTab('send'); setIsSendMoneyOpen(true); }} onToggleMenu={() => setIsMenuOpen(!isMenuOpen)} />
        </div>
    );
};

