    const costPerPerson = (parseFloat(amount) || 0) / (selectedFriends.size + 1);

    return (
        <div className="h-full flex flex-col p-6 space-y-6">
            <div className="bg-black/30 rounded-2xl p-6 border border-white/5 text-center">
