                            <div className="text-left flex-1">
                                <p className="text-xs font-bold text-white">{rec.fullName}</p>
                            </div>
                            {selectedFriends.has(rec.id) && <CheckCircleIcon className="w-4 h-4 text-primary" />}
                        </button>
                    ))}
                </div>
            </div>

            {selectedFriends.size > 0 && (
                <button 
                    onClick={() => onSplit(parseFloat(amount), recipients.filter(r => selectedFriends.has(r.id)))}
