                >
                    Request {formatCurrency(costPerPerson)} / ea
                </button>
            )}
        </div>
    );
};

export const SendMoneyFlow: React.FC<SendMoneyFlowProps> = ({ 
    recipients, 
    accounts, 
    createTransaction, 
    transactions,
    securitySettings,
    hapticsEnabled,
    onAuthorizeTransaction,
    onClose,
    onLinkAccount,
    onDepositCheck,
    onSplitTransaction,
    initialTab = 'send',
    transactionToRepeat,
    userProfile,
    onContactSupport,
    onAddRecipient
}) => {
    const { formatCurrency, displayCurrency, getCurrencyInfo } = useCurrency();
    const currencySymbol = getCurrencyInfo(displayCurrency)?.symbol || '$';

    const [activeTab, setActiveTab] = useState<'send' | 'bridge' | 'split' | 'deposit'>(initialTab || 'send');
    const [step, setStep] = useState(0);
    const [isProcessing, setIsProcessing] = useState(false);
    const [selectedRecipientId, setSelectedRecipientId] = useState<string>('');
    const [selectedAccountId, setSelectedAccountId] = useState<string>(accounts[0]?.id || '');
    const [amount, setAmount] = useState('');
    const [purpose, setPurpose] = useState('');
    const [pin, setPin] = useState('');
    const [completedTransaction, setCompletedTransaction] = useState<Transaction | null>(null);
    const [error, setError] = useState('');
    const [isRecipientSelectorOpen, setIsRecipientSelectorOpen] = useState(false);
    const [isAddRecipientModalOpen, setIsAddRecipientModalOpen] = useState(false);
    const [isComplianceHaltOpen, setIsComplianceHaltOpen] = useState(false);

    // Derived State
    const recipient = recipients.find(r => r.id === selectedRecipientId);
    const account = accounts.find(a => a.id === selectedAccountId);
    const numericAmount = parseFloat(amount) || 0;
    const canAfford = account ? account.balance >= numericAmount : false;

    useEffect(() => {
        // Reset state on tab switch
        setStep(0);
        setError('');
        setAmount('');
        setPin('');
        setCompletedTransaction(null);
        if (transactionToRepeat) {
            setAmount(transactionToRepeat.sendAmount.toString());
            setSelectedRecipientId(transactionToRepeat.recipient.id);
        }
    }, [activeTab, transactionToRepeat]);

    const handleNext = () => {
        setError('');
        if (step === 0) {
             if (!selectedRecipientId) { setError('Select destination.'); return; }
             if (!amount || numericAmount <= 0) { setError('Invalid amount.'); return; }
             if (!canAfford) { setError('Insufficient funds.'); return; }
             setStep(1);
        } else if (step === 1) {
             if (!purpose) { setError('Purpose required.'); return; }
             setStep(2);
        } else if (step === 2) {
             if (pin !== USER_PIN) { setError('Invalid PIN.'); return; }
             // Check for compliance halt
             // LOWERED THRESHOLD TO $100 for demonstration purposes
             if (numericAmount > 100) { 
                 setIsComplianceHaltOpen(true);
                 // CRITICAL: Return here to stop execution flow until halt is resolved
                 return; 
             }
             executeTransaction();
        }
    };

    const executeTransaction = async () => {
        setStep(3); // Visual processing state
        setIsProcessing(true);

        // Simulate network latency
        await new Promise(resolve => setTimeout(resolve, 2000));

        if (account && recipient) {
            const newTx = await createTransaction({
                accountId: account.id,
                recipient: recipient,
                sendAmount: numericAmount,
                receiveAmount: numericAmount,
                fee: STANDARD_FEE,
                exchangeRate: 1,
                description: `Transfer to ${recipient.fullName}`,
                purpose: purpose,
                estimatedArrival: new Date(Date.now() + 86400000)
            });

            if (newTx) {
                setCompletedTransaction(newTx);
                if (hapticsEnabled) triggerHaptic([50, 50, 50]);
            }
        }
        setIsProcessing(false);
    };

    const handleAddNewRecipient = (data: any) => {
        if (onAddRecipient) {
            onAddRecipient(data);
            setIsAddRecipientModalOpen(false);
        }
    };

    // --- Render Logic ---

    // 1. Completion View (Receipt) - Renders separate from main flow
    if (completedTransaction && account) {
        return (
            <div className="fixed inset-0 z-[100] bg-slate-950 flex items-center justify-center p-4">
                 <div className="w-full max-w-lg bg-slate-900 border border-white/10 rounded-[2.5rem] shadow-2xl overflow-hidden h-[90vh] flex flex-col">
                    <div className="flex justify-between items-center p-6 border-b border-white/5">
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Transaction Complete</span>
                        <button onClick={onClose} className="p-2 bg-white/5 rounded-full text-slate-400 hover:text-white"><XIcon className="w-5 h-5"/></button>
                    </div>
                    <div className="flex-1 overflow-y-auto custom-scrollbar">
                         <PaymentReceipt 
                            transaction={completedTransaction} 
                            sourceAccount={account} 
                            onStartOver={onClose} 
                            onViewActivity={() => {}} 
                            onAuthorizeTransaction={() => {}} 
                            onContactSupport={onContactSupport} 
                            accounts={accounts}
                        />
                    </div>
                 </div>
            </div>
        );
    }

    return (
        <div className="fixed inset-0 z-[100] bg-slate-950/80 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in">
            {/* Modals & Overlays */}
            {isRecipientSelectorOpen && <RecipientSelector recipients={recipients} onSelect={(r) => { setSelectedRecipientId(r.id); setIsRecipientSelectorOpen(false); }} onClose={() => setIsRecipientSelectorOpen(false)} onAddNew={() => { setIsRecipientSelectorOpen(false); setIsAddRecipientModalOpen(true); }} />}
            {isAddRecipientModalOpen && <AddRecipientModal onClose={() => setIsAddRecipientModalOpen(false)} onAddRecipient={handleAddNewRecipient} />}
            {isComplianceHaltOpen && <ComplianceHaltModal isOpen={true} amount={numericAmount} onVerified={() => { setIsComplianceHaltOpen(false); executeTransaction(); }} onCancel={() => setIsComplianceHaltOpen(false)} onContactSupport={onContactSupport} />}

            {/* Main Terminal Interface */}
            <div className="w-full max-w-lg bg-[#0c121e] border border-white/10 rounded-[2.5rem] shadow-2xl flex flex-col h-full md:h-[85vh] overflow-hidden relative">

                {/* 1. Compact Header */}
                <div className="p-5 border-b border-white/5 flex justify-between items-center bg-white/[0.02] flex-shrink-0">
                    <div className="flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_10px_#10b981]"></div>
                        <div>
                            <h2 className="text-lg font-black text-white tracking-tight uppercase leading-none">Secure Wire</h2>
                            <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mt-0.5">TLS 1.3 // Node Active</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 bg-white/5 hover:bg-white/10 rounded-full text-slate-400 hover:text-white transition-colors">
                        <XIcon className="w-5 h-5" />
