                        {step > 0 ? (
                            <button onClick={() => setStep(prev => prev - 1)} className="px-5 py-4 rounded-xl bg-white/5 hover:bg-white/10 text-slate-400 font-bold text-xs uppercase tracking-wider transition-colors">
