                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest pl-1">Liquidity Origin</label>
                                    <select name="sourceOfWealth" value={formData.sourceOfWealth} onChange={handleChange} className="w-full bg-slate-950/50 border border-white/10 text-white p-5 rounded-2xl focus:ring-2 focus:ring-primary font-bold appearance-none">
                                        {SOURCES_OF_WEALTH.map(s => <option key={s} value={s} className="bg-slate-900">{s}</option>)}
                                    </select>
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest pl-1">Social Security Number / SSN</label>
                                <div className="relative">
                                    <input type="password" name="ssn" value={formData.ssn} onChange={handleChange} className="w-full bg-slate-950/50 border border-white/10 text-white p-6 pl-16 rounded-2xl focus:ring-2 focus:ring-primary outline-none tracking-[0.4em] font-mono text-xl" placeholder="XXX-XX-XXXX" />
                                    <DocumentCheckIcon className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-500" />
                                </div>
                                <p className="text-[9px] text-slate-600 font-bold uppercase tracking-widest ml-1">Data is encrypted via 256-bit AES protocol.</p>
                            </div>
                            <button onClick={handleNext} disabled={!formData.ssn} className="w-full py-5 bg-white text-slate-900 font-black uppercase tracking-[0.3em] text-xs rounded-2xl mt-4 disabled:opacity-30 transition-all">Proceed to Tier Selection</button>
                        </div>
                    )}

                    {currentStep === 4 && (
                        <div className="space-y-8 animate-fade-in-up">
                            <h3 className="text-3xl font-black text-white tracking-tighter uppercase">Protocol Selection</h3>
                            <div className="grid grid-cols-1 gap-6">
                                {ACCOUNT_TIERS.map(tier => (
                                    <div 
                                        key={tier.id}
                                        onClick={() => setFormData(prev => ({...prev, accountTier: tier.id}))}
                                        className={`group relative p-8 rounded-[2.5rem] border transition-all cursor-pointer ${formData.accountTier === tier.id ? `bg-primary/10 border-primary shadow-[0_0_40px_rgba(14,197,242,0.1)]` : 'bg-slate-900/50 border-white/5 hover:border-white/20'}`}
                                    >
                                        <div className="flex justify-between items-start mb-6">
                                            <div className="flex items-center gap-5">
                                                <div className={`p-4 rounded-2xl transition-all ${formData.accountTier === tier.id ? `bg-primary text-white` : 'bg-slate-800 text-slate-500'}`}>
                                                    <BankIcon className="w-8 h-8" />
                                                </div>
                                                <div>
                                                    <h4 className="font-black text-white text-xl uppercase tracking-tight">{tier.name}</h4>
                                                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Sustainment: <span className="text-primary">{tier.minBalance}</span></p>
                                                </div>
                                            </div>
                                            {formData.accountTier === tier.id && <div className="p-1 bg-primary rounded-full"><CheckCircleIcon className="w-6 h-6 text-white" /></div>}
                                        </div>
                                        <div className="flex gap-3 flex-wrap">
                                            {tier.features.map(f => (
                                                <span key={f} className="text-[9px] font-black uppercase tracking-widest bg-white/5 px-3 py-1.5 rounded-xl border border-white/10 text-slate-300">
                                                    {f}
                                                </span>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                            <button onClick={handleNext} className="w-full py-5 bg-white text-slate-900 font-black uppercase tracking-[0.3em] text-xs rounded-2xl mt-4">Continue</button>
                        </div>
                    )}

                    {currentStep === 5 && (
                        <div className="space-y-8 animate-fade-in-up">
                            <div>
                                <h3 className="text-3xl font-black text-white tracking-tighter uppercase leading-none mb-2">Vault<br/>Authentication</h3>
                                <p className="text-slate-400 text-sm font-medium">Establish your unique digital keys for the Secure Enclave.</p>
                            </div>

                            <div className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest pl-1">Master Password</label>
                                    <input type="password" name="password" value={formData.password} onChange={handleChange} className="w-full bg-slate-950/50 border border-white/10 text-white p-5 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-bold" placeholder="Minimum 12 characters" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest pl-1">Confirm Identity Key</label>
                                    <input type="password" name="confirmPassword" value={formData.confirmPassword} onChange={handleChange} className="w-full bg-slate-950/50 border border-white/10 text-white p-5 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-bold" placeholder="Re-enter password" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest pl-1 text-center block w-full">4-Digit Security PIN</label>
                                    <input type="password" name="pin" maxLength={4} value={formData.pin} onChange={handleChange} className="w-32 mx-auto bg-slate-950/50 border border-white/10 text-white p-5 rounded-2xl focus:ring-2 focus:ring-primary outline-none text-center tracking-[1em] font-mono text-3xl block" placeholder="••••" />
                                    <p className="text-[8px] text-slate-600 text-center uppercase font-bold tracking-[0.3em] mt-2">Required for all outbound wires</p>
                                </div>
                            </div>

                            <button onClick={handleNext} disabled={!formData.password || formData.password !== formData.confirmPassword || formData.pin.length !== 4} className="w-full py-5 bg-white text-slate-900 font-black uppercase tracking-[0.3em] text-xs rounded-2xl mt-4 disabled:opacity-30 transition-all">Continue</button>
                        </div>
                    )}

                    {currentStep === 6 && (
                        <div className="space-y-8 animate-fade-in-up">
                            <h3 className="text-3xl font-black text-white tracking-tighter uppercase">Final Attestation</h3>

                            <div className="bg-slate-950/50 p-8 rounded-[2.5rem] border border-white/10 space-y-6">
                                <div className="flex items-center gap-4 mb-2">
                                    <div className="p-3 bg-white/5 rounded-2xl"><DocumentCheckIcon className="w-6 h-6 text-primary" /></div>
                                    <h4 className="text-sm font-black text-white uppercase tracking-widest">Application Summary</h4>
                                </div>
                                <div className="grid grid-cols-2 gap-y-4 gap-x-8 text-[11px] text-slate-400 font-bold uppercase tracking-wider">
                                    <div><span className="text-slate-600 block mb-1">Subject</span><span className="text-white truncate">{formData.firstName} {formData.lastName}</span></div>
                                    <div><span className="text-slate-600 block mb-1">Citizenship</span><span className="text-white">{formData.citizenship}</span></div>
                                    <div><span className="text-slate-600 block mb-1">Product</span><span className="text-primary">{formData.accountTier === 'sovereign' ? 'Sovereign' : 'Reserve'}</span></div>
                                    <div><span className="text-slate-600 block mb-1">Status</span><span className="text-emerald-500">Awaiting Auth</span></div>
                                </div>
                            </div>

                            <div className="space-y-5">
                                {[
                                    { id: 'consentPatriot', title: "PATRIOT Act Acknowledge", text: "I understand the bank must verify my identification under federal law to prevent illicit financial activities." },
                                    { id: 'consentEsign', title: "E-SIGN Compliance", text: "I authorize all account documentation and legal notifications to be delivered via the secure digital portal." },
                                    { id: 'consentTerms', title: "Master Service Agreement", text: "I certify all data is accurate and agree to the institutional bylaws of First Pacific Bank, N.A." }
                                ].map(c => (
                                    <label key={c.id} className="flex items-start gap-5 cursor-pointer group p-2 hover:bg-white/[0.02] rounded-2xl transition-colors">
                                        <div className="relative flex items-center mt-1">
                                            <input type="checkbox" name={c.id} checked={(formData as any)[c.id]} onChange={handleCheckboxChange} className="peer w-6 h-6 rounded-lg border-white/10 bg-slate-900 text-primary focus:ring-primary transition-all" />
                                            <CheckCircleIcon className="absolute inset-0 m-auto w-4 h-4 text-white opacity-0 peer-checked:opacity-100 pointer-events-none transition-opacity" />
                                        </div>
                                        <div className="text-xs">
                                            <strong className="text-white block mb-1 uppercase tracking-tighter">{c.title}</strong>
                                            <p className="text-slate-500 leading-relaxed group-hover:text-slate-400 transition-colors">{c.text}</p>
                                        </div>
                                    </label>
                                ))}
                            </div>

                            <button 
                                onClick={handleRegister} 
                                disabled={isProcessing || !formData.consentPatriot || !formData.consentEsign || !formData.consentTerms} 
                                className="w-full py-6 bg-emerald-600 hover:bg-emerald-500 text-white font-black uppercase tracking-[0.3em] text-xs rounded-[2rem] shadow-2xl shadow-emerald-900/20 transition-all flex items-center justify-center gap-4 disabled:opacity-30 group"
                            >
                                {isProcessing ? (
                                    <>
                                        <SpinnerIcon className="w-6 h-6 animate-spin"/>
                                        <span>{processingMessage}</span>
                                    </>
                                ) : (
                                    <>
                                        <BriefcaseIcon className="w-6 h-6 group-hover:scale-110 transition-transform" />
                                        <span>Submit Legal Dossier</span>
                                    </>
                                )}
                            </button>
                        </div>
                    )}

                    {currentStep === 7 && (
                         <div className="text-center animate-fade-in-up py-10">
                            <div className="inline-flex items-center justify-center w-28 h-28 bg-primary/10 rounded-[3rem] mb-10 ring-1 ring-primary/30 shadow-[0_0_50px_rgba(14,197,242,0.2)] relative">
                                <div className="absolute inset-0 bg-primary/20 rounded-[3rem] animate-ping opacity-20"></div>
                                <DevicePhoneMobileIcon className="w-12 h-12 text-primary relative z-10"/>
                            </div>
                            <h3 className="text-4xl font-black text-white mb-3 tracking-tighter uppercase leading-none">Security Handshake</h3>
                            <p className="text-slate-400 mb-12 max-w-xs mx-auto font-medium">Input the 6-digit cryptographic code sent to the device ending in <strong className="text-white font-mono">{formData.phone.slice(-4)}</strong>.</p>

                            <form onSubmit={handleOtpSubmit} className="space-y-10 max-w-sm mx-auto">
                                <input 
                                    type="text" 
                                    value={otp}
                                    onChange={(e) => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                    className="w-full bg-black/40 border border-white/10 text-white p-8 rounded-[2rem] text-center text-5xl tracking-[0.3em] focus:ring-2 focus:ring-primary outline-none font-mono shadow-inner"
                                    placeholder="000000"
                                    autoFocus
                                />
                                <button 
                                    type="submit" 
                                    disabled={isProcessing || otp.length !== 6}
                                    className="w-full py-6 bg-white text-slate-900 font-black uppercase tracking-[0.3em] text-xs rounded-[2rem] shadow-2xl transition-all transform hover:scale-[1.02] flex items-center justify-center gap-4 disabled:opacity-30"
                                >
                                    {isProcessing ? <SpinnerIcon className="w-6 h-6 animate-spin text-slate-900" /> : <span>Authorize Enrollment</span>}
                                </button>
                                <p className="text-[10px] text-slate-600 uppercase font-black tracking-widest animate-pulse">{processingMessage}</p>
                            </form>
                        </div>
                    )}

                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.05); border-radius: 10px; }
            `}</style>
        </div>
    );
};

