// --- Brand Logo Component ---
export const BrandLogo = ({ 
    domain, 
    name, 
    fallback: Fallback, 
    className 
}: { 
    domain?: string; 
    name: string; 
    fallback: React.ComponentType<{ className?: string }>; 
    className?: string 
}) => {
    const [logoUrl, setLogoUrl] = useState<string | null>(null);
    const [imgState, setImgState] = useState<'loading' | 'loaded' | 'error'>('loading');

    useEffect(() => {
        let isMounted = true;
        setImgState('loading');
        setLogoUrl(null);

        if (!domain) {
            if (isMounted) setImgState('error');
            return;
        }

        const loadLogo = async () => {
            // Priority 1: Clearbit
            const clearbitUrl = `https://logo.clearbit.com/${domain}`;

            // Image object to pre-validate availability
            const img = new Image();
            img.src = clearbitUrl;

            img.onload = () => {
                if (isMounted) {
                    setLogoUrl(clearbitUrl);
                    setImgState('loaded');
                }
            };

            img.onerror = () => {
                if (isMounted) {
                    // Priority 2: Google Favicon (Fallback)
                    const googleUrl = `https://www.google.com/s2/favicons?domain=${domain}&sz=128`;
                    setLogoUrl(googleUrl);
                    // Assume Google always returns *something* (default globe if not found)
                    setImgState('loaded');
                }
            };
        };

        loadLogo();
        return () => { isMounted = false; };
    }, [domain]);

    if (imgState === 'error' || !logoUrl) {
        return <Fallback className={className} />;
    }

    return (
        <img 
            src={logoUrl} 
            alt={name} 
            className={`${className} transition-opacity duration-300 ${imgState === 'loaded' ? 'opacity-100' : 'opacity-0'}`} 
            onLoad={() => setImgState('loaded')}
            onError={() => setImgState('error')}
        />
    );
};

