                         <div className="mt-4 max-h-[70vh] overflow-y-auto">
                            <ul className="space-y-1">
                                {searchResults.accounts.length > 0 && (
                                    <li className="px-2 pt-3 pb-1 text-xs font-bold text-primary uppercase tracking-wider">Accounts</li>
                                )}
                                {searchResults.accounts.map(acc => (
                                    <li key={acc.id}><Link to="/accounts" onClick={() => setIsMobileSearchOpen(false)} className="flex items-center gap-3 px-2 py-2 hover:bg-white/5 text-sm text-slate-300 rounded-lg"><BankIcon className="w-4 h-4" />{acc.nickname || acc.type}</Link></li>
                                ))}
                                {searchResults.recipients.length > 0 && (
                                    <li className="px-2 pt-3 pb-1 text-xs font-bold text-primary uppercase tracking-wider">Recipients</li>
                                )}
                                {searchResults.recipients.map(rec => (
                                    <li key={rec.id}><Link to="/recipients" onClick={() => setIsMobileSearchOpen(false)} className="flex items-center gap-3 px-2 py-2 hover:bg-white/5 text-sm text-slate-300 rounded-lg"><UserGroupIcon className="w-4 h-4" />{rec.fullName}</Link></li>
                                ))}
                                 {searchResults.transactions.length > 0 && (
                                    <li className="px-2 pt-3 pb-1 text-xs font-bold text-primary uppercase tracking-wider">Transactions</li>
                                )}
                                {searchResults.transactions.map(tx => (
                                    <li key={tx.id}><Link to="/history" onClick={() => setIsMobileSearchOpen(false)} className="flex items-center gap-3 px-2 py-2 hover:bg-white/5 text-sm text-slate-300 rounded-lg"><ActivityIcon className="w-4 h-4" />{tx.description}</Link></li>
                                ))}
                            </ul>
                        </div>
                    )}
                </div>
                <button onClick={() => setIsMobileSearchOpen(false)} className="absolute top-4 right-4 p-2 text-slate-400">
                    <XIcon className="w-6 h-6" />
                </button>
            </div>
        )}
      </header>
    </>
  );
};

