export const MegaMenu: React.FC<MegaMenuProps> = ({ isOpen, onClose, userProfile, onOpenSendMoneyFlow, onOpenWireTransfer, onOpenLogoutConfirm }) => {
    const [hoveredCategory, setHoveredCategory] = useState<MenuCategory>('Banking');
    const { t } = useLanguage();
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') onClose();
        };
        if (isOpen) {
            document.addEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'hidden';
        }
        return () => {
            document.removeEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'auto';
        };
    }, [isOpen, onClose]);

    const handleModalItemClick = (view: View) => {
        if (view === 'send') onOpenSendMoneyFlow('send');
        else if (view === 'wire') onOpenWireTransfer();
        onClose();
    };

    const renderMenuItem = (item: any) => {
        const Icon = item.icon;
        const isModalTrigger = item.view === 'send' || item.view === 'wire';

        const content = ({ isActive }: { isActive?: boolean } = {}) => (
            <>
                <div className={`flex-shrink-0 w-10 h-10 flex items-center justify-center rounded-xl transition-all duration-300 ${
                    isActive ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-slate-800 text-slate-400 group-hover:text-primary group-hover:bg-primary/10'
                }`}>
                    <Icon className="w-5 h-5" />
                </div>
                <div>
                    <p className={`font-bold text-sm transition-colors ${isActive ? 'text-white' : 'text-slate-300 group-hover:text-white'}`}>{t(item.labelKey)}</p>
                    <p className="text-[10px] text-slate-500 group-hover:text-slate-400 uppercase tracking-wider font-medium">{item.description}</p>
                </div>
            </>
        );

        if (isModalTrigger) {
            return (
                <button
                    onClick={() => handleModalItemClick(item.view)}
                    className="w-full group flex items-center gap-4 p-3 rounded-2xl text-left transition-all duration-300 border border-transparent hover:bg-white/5 hover:border-white/5 hover:translate-x-1"
                >
                    {content()}
                </button>
            );
        }

        return (
            <NavLink
                to={`/${item.view}`}
                onClick={onClose}
                className={({ isActive }: { isActive: boolean }) =>
                    `w-full group flex items-center gap-4 p-3 rounded-2xl text-left transition-all duration-300 border border-transparent ${
                        isActive 
                        ? 'bg-primary/10 border-primary/30 shadow-[0_0_20px_rgba(14,197,242,0.1)]' 
                        : 'hover:bg-white/5 hover:border-white/5 hover:translate-x-1'
                    }`
                }
            >
                {({ isActive }: { isActive: boolean }) => content({ isActive })}
            </NavLink>
        );
    };

