        <>
            {/* Backdrop Blur */}
            <div
                className={`fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[90] transition-opacity duration-700 ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
